diagrams.source:
flowchart TB
  CD@{ svc: "AWS CodeDeploy", label: "ECS の blue/green デプロイ" }
  NLB["⚠ A・B: Network Load Balancer では ECSAllAtOnce しか使えない"]
  LB@{ svc: "Elastic Load Balancing", label: "✔ D: Application Load Balancer に替える" }
  OLD@{ svc: "Amazon ECS", label: "旧タスクセット" }
  NEW@{ svc: "Amazon ECS", label: "新タスクセット" }
  BADC["⚠ C: 承認を足しても一度に全部移る"]
  CD -- "ECSCanary10Percent5Minutes" --> LB
  LB == "✔ D: 最初の 10% を 5 分" ==> NEW
  LB -- "その後に残り" --> OLD
  NLB -.-> CD
  BADC -.-> CD

flowchart TB
  subgraph TASK["Fargate 上の ECS タスク"]
    AG@{ svc: "AWS Fargate", label: "エージェント（イメージを取得）" }
    APP@{ svc: "Amazon ECS", label: "コンテナのアプリ" }
  end
  ER@{ svc: "AWS IAM", label: "✔ A: タスク実行ロール" }
  TR@{ svc: "AWS IAM", label: "✔ B: タスクの IAM ロール" }
  ECR@{ svc: "Amazon ECR", label: "プライベートリポジトリ" }
  S3@{ svc: "Amazon S3", label: "バケット" }
  BAD["⚠ C・D: 権限を付けるロールが逆では届かない"]
  ER -- "取得の権限" --> AG
  AG == "イメージの取得" ==> ECR
  TR -- "S3 への書き込み" --> APP
  APP == "オブジェクトを書く" ==> S3
  BAD -.-> TASK
